async function runUpdate($: EngineInterface, card: UpdateCard) {
  await update($, updateCard, () => ({ ...card, stage: 'updating' }))
  const step = async (args: string[]) => {
    const r = await runClaude($, args, { timeoutMs: 180_000, env: GITHUB_OVER_HTTPS })
